fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let orig_len = orig.len();
    let width_usize = width as usize;
    
    // If original length is already >= width, return original unchanged
    if orig_len >= width_usize {
        return orig;
    }
    
    // Calculate how many padding characters we need
    let padding_len = width_usize - orig_len;
    
    // Create result vector with pre-allocated capacity
    let mut result = Vec::with_capacity(width_usize);
    
    // Add padding characters
    for _ in 0..padding_len {
        result.push(fillchar);
    }
    
    // Add original characters
    result.extend(orig);
    
    result
}